{"evals/relevance/audit.ts":"// Corpus audit: is there subject matter for any ranker to match on?
import type { Item } from "./blind.ts";

export interface SourceAudit {
  items: number;
  withSummary: number;
  avgSummaryChars: number;
  topicsFromTitle: number;
}

export interface CorpusAudit {
  sources: Record<string, SourceAudit>;
  starvedSources: string[];
  finding: "subject-matter-absent" | "ranker-ordering";
}

const tokens = (title: string) => new Set(title.toLowerCase().split(/[^a-z]+/).filter(Boolean));

export function auditCorpus(items: readonly Item[], governmentSources: readonly string[]): CorpusAudit {
  const grouped = new Map<string, Item[]>();
  for (const item of items) grouped.set(item.source, [...(grouped.get(item.source) ?? []), item]);
  const sources: Record<string, SourceAudit> = {};
  for (const [source, group] of grouped) {
    const summaries = group.map((item) => (item.summary ?? "").trim()).filter((text) => text.length > 0);
    sources[source] = {
      items: group.length,
      withSummary: summaries.length,
      avgSummaryChars: summaries.length
        ? Math.round(summaries.reduce((sum, text) => sum + text.length, 0) / summaries.length) : 0,
      topicsFromTitle: group.filter((item) => {
        const words = tokens(item.title);
        return item.topics.length > 0 && item.topics.every((topic) => words.has(topic.toLowerCase()));
      }).length,
    };
  }
  const starved = governmentSources.filter((source) => {
    const group = grouped.get(source) ?? [];
    const substantive = group.filter((item) => (item.summary ?? "").trim().length >= 80).length;
    return substantive * 2 < group.length;
  }).sort();
  return {
    sources,
    starvedSources: starved,
    finding: governmentSources.length > 0 && starved.length === governmentSources.length
      ? "subject-matter-absent" : "ranker-ordering",
  };
}
","evals/relevance/blind.ts":"// Blind projection for rating: no evaluative field may reach the reader.
export const EVALUATIVE_KEYS = ["score", "matched", "reasons", "rank", "matchedNorthStars", "arm"] as const;

export interface Item {
  id: string;
  source: string;
  title: string;
  summary?: string;
  topics: string[];
  [key: string]: unknown;
}

export interface BlindItem {
  id: string;
  source: string;
  title: string;
  summary: string;
}

export function assertNothingEvaluative(value: unknown, path = "$"): void {
  if (Array.isArray(value)) {
    value.forEach((child, index) => assertNothingEvaluative(child, `${path}[${index}]`));
    return;
  }
  if (value !== null && typeof value === "object") {
    for (const [key, child] of Object.entries(value)) {
      if ((EVALUATIVE_KEYS as readonly string[]).includes(key)) {
        throw new Error(`evaluative field ${key} at ${path}`);
      }
      assertNothingEvaluative(child, `${path}.${key}`);
    }
  }
}

export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function seededShuffle<T>(values: readonly T[], seed: number): T[] {
  const out = [...values];
  const next = mulberry32(seed);
  for (let i = out.length - 1; i > 0; i -= 1) {
    const j = Math.floor(next() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

export function blindItems(items: readonly Item[], seed: number): BlindItem[] {
  const projected = items.map((item) => ({ id: item.id, source: item.source, title: item.title,
    summary: item.summary ?? "" }));
  const result = seededShuffle(projected, seed);
  assertNothingEvaluative(result);
  return result;
}
","evals/relevance/score.ts":"// Scores one ranking arm against blind ratings; can report misses and wrong reasons.
export interface Rating {
  relevance: 0 | 1 | 2;
  reasonAccepted?: boolean;
}

export interface Arm {
  name: string;
  ranking: string[];
}

export interface ArmScore {
  precisionAtK: number;
  ndcgAtK: number;
  misses: string[];
  wrongReasons: string[];
  firedCount: number;
}

const round4 = (value: number) => Math.round(value * 10000) / 10000;

function dcg(gains: number[]): number {
  return gains.reduce((sum, gain, index) => sum + gain / Math.log2(index + 2), 0);
}

export function scoreArm(arm: Arm, ratings: Record<string, Rating>, k: number): ArmScore {
  const shown = arm.ranking.slice(0, k);
  const shownSet = new Set(shown);
  const relevance = (id: string) => ratings[id]?.relevance ?? 0;
  const ideal = Object.values(ratings).map((r) => r.relevance).sort((a, b) => b - a).slice(0, k);
  const idcg = dcg(ideal);
  return {
    precisionAtK: round4(shown.filter((id) => relevance(id) >= 1).length / k),
    ndcgAtK: idcg === 0 ? 0 : round4(dcg(shown.map(relevance)) / idcg),
    misses: Object.keys(ratings).filter((id) => ratings[id].relevance === 2 && !shownSet.has(id)).sort(),
    wrongReasons: shown.filter((id) => relevance(id) >= 1 && ratings[id]?.reasonAccepted === false).sort(),
    firedCount: shown.length,
  };
}
