const mod = (name) => import(`${R}/${name}.ts`);
const threw = (fn) => { try { fn(); return false; } catch (error) { return error instanceof Error; } };

export async function blindHeld() {
  const { blindItems } = await mod("blind");
  const before = JSON.stringify(DATA.held);
  const out = blindItems(DATA.held, 1234);
  return { ids: out.map((x) => x.id), keys: [...new Set(out.flatMap((x) => Object.keys(x)))].sort(),
    summariesAreStrings: out.every((x) => typeof x.summary === "string"),
    emptyForMissing: out.filter((x) => x.summary === "").length, unmutated: JSON.stringify(DATA.held) === before };
}
export async function blindOtherSeed() {
  const { blindItems } = await mod("blind");
  return { ids: blindItems(DATA.held, 1235).map((x) => x.id), again: blindItems(DATA.held, 1234).map((x) => x.id) };
}
export async function assertDeep() {
  const { assertNothingEvaluative } = await mod("blind");
  return { nested: threw(() => assertNothingEvaluative({ a: [{ b: { rank: 1 } }] })),
    topLevel: threw(() => assertNothingEvaluative([{ id: "x", arm: "keyword" }])),
    northStars: threw(() => assertNothingEvaluative({ x: { matchedNorthStars: [] } })),
    clean: threw(() => assertNothingEvaluative({ id: "x", title: "rank and score words are fine", list: [1, "score"] })) };
}
export async function scoreKeyword() { return (await mod("score")).scoreArm({ name: "keyword", ranking: DATA.arms.keyword }, DATA.held_ratings, 5); }
export async function scoreAlternative() { return (await mod("score")).scoreArm({ name: "alternative", ranking: DATA.arms.alternative }, DATA.held_ratings, 10); }
export async function scoreUnrated() { return (await mod("score")).scoreArm({ name: "k", ranking: ["zz-unrated", ...DATA.arms.keyword] }, DATA.held_ratings, 3); }
export async function scoreZeroIdeal() { return (await mod("score")).scoreArm({ name: "z", ranking: ["a", "b"] }, { a: { relevance: 0 }, b: { relevance: 0 } }, 2); }
export async function auditHeld() { return (await mod("audit")).auditCorpus(DATA.held, DATA.gov); }
export async function auditGood() { return (await mod("audit")).auditCorpus(DATA.held_good, DATA.gov); }

